    // Optimized schedule for the 3D stencil updates.
    //
    // Layout:
    //   Buffer dims: (k, j, i) with k as the innermost (stride-1) dim.
    // Strategy:
    //   - Keep k innermost for unit-stride, cache-friendly access.
    //   - Vectorize along k using the natural SIMD width.
    //   - Parallelize along the outermost dimension i (independent z-slices).
    //   - Explicitly bound the computation domain to the interior
    //     region [1, n-2] in each dimension, which matches the
    //     cropped views we realize into. This avoids any work on
    //     the boundaries and makes the loop structure explicit.
    // ------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Schedule for B_from_A: B = stencil(A)
    B_from_A
        .compute_root()
        // Restrict the domain to the interior region we actually update.
        .bound(k, 1, n - 2)
        .bound(j, 1, n - 2)
        .bound(i, 1, n - 2)
        // Ensure loop order: k innermost, then j, then i outermost.
        .reorder(k, j, i)
        // Vectorize contiguous k dimension.
        .vectorize(k, vec_width)
        // Parallelize across independent i-slices.
        .parallel(i);

