            B_param(k,     j,     i - 1) +
            B_param(k,     j + 1, i    ) +
            B_param(k,     j - 1, i    ) +
            B_param(k + 1, j,     i    ) +
            B_param(k - 1, j,     i    ) -
            six * centerB;

