    Expr val = cast<num_t>(i + j + (n - k)) *
               cast<num_t>(Expr(10.0)) /
               cast<num_t>(Expr(n));
    init(k, j, i) = val;

    // Simple schedule for initialization: make k (the contiguous
    // memory dimension) innermost, vectorize over it, and parallelize
    // outermost i to use multiple cores.
    {
        Target target = get_host_target();
        const int vec_width = target.natural_vector_size<num_t>();

        init
            .reorder(k, j, i)     // innermost -> outermost: k, j, i
            .parallel(i);         // parallelize across i-planes

        if (vec_width > 1) {
            init.vectorize(k, vec_width);
        }
    }

    // Realize into both A and B so that B initially equals A
    init.realize(A);
    init.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size and number of time steps.
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate 3D buffers.
    // Dimension order is (k, j, i) so that:
    //   A(i,j,k in C) <-> A(k, j, i) in Halide.
    // This keeps the k dimension contiguous in memory, matching C.
    Halide::Buffer<num_t, 3> A(n, n, n);
    Halide::Buffer<num_t, 3> B(n, n, n);

    // Initialize A and B.
    init_array(n, A, B);

    // Create ImageParams for A and B so that Halide pipelines can read them.
    ImageParam A_param(type_of<num_t>(), 3, "A_param");
    ImageParam B_param(type_of<num_t>(), 3, "B_param");

    A_param.set(A);
    B_param.set(B);

    // Vars for 3D indexing (k, j, i) <-> (C's k, j, i).
    Var k("k"), j("j"), i("i");

    // One time-step consists of:
    //   1) B = stencil(A)
    //   2) A = stencil(B)
    //
    // We'll express these as two separate Halide Funcs:
    //   B_from_A: reads A_param, writes into B
    //   A_from_B: reads B_param, writes into A
    //
    // We only update interior points (i,j,k in [1, n-2]), as in the
    // original C loops. The boundaries remain unchanged.
    Func B_from_A("B_from_A");
    Func A_from_B("A_from_B");

    // Coefficients used in the stencil.
    Expr alpha = cast<num_t>(Expr(0.125));  // diffusion coefficient
    Expr two   = cast<num_t>(Expr(2.0));

    // --- Stage 1: B = stencil(A) ---
    {
        // Cache all neighbor values into Exprs so each element of A is
        // loaded from memory only once per update point. Halide's
        // simplifier will also help, but this makes the intent explicit.
        Expr centerA = A_param(k, j, i);

        Expr A_ip = A_param(k, j, i + 1);
        Expr A_im = A_param(k, j, i - 1);
        Expr A_jp = A_param(k, j + 1, i);
        Expr A_jm = A_param(k, j - 1, i);
        Expr A_kp = A_param(k + 1, j, i);
        Expr A_km = A_param(k - 1, j, i);

        Expr term_i = alpha * (A_ip - two * centerA + A_im);
        Expr term_j = alpha * (A_jp - two * centerA + A_jm);
        Expr term_k = alpha * (A_kp - two * centerA + A_km);

        B_from_A(k, j, i) = term_i + term_j + term_k + centerA;
    }

    // --- Stage 2: A = stencil(B) ---
    {
        Expr centerB = B_param(k, j, i);

        Expr B_ip = B_param(k, j, i + 1);
        Expr B_im = B_param(k, j, i - 1);
        Expr B_jp = B_param(k, j + 1, i);
        Expr B_jm = B_param(k, j - 1, i);
        Expr B_kp = B_param(k + 1, j, i);
        Expr B_km = B_param(k - 1, j, i);

        Expr term_i = alpha * (B_ip - two * centerB + B_im);
        Expr term_j = alpha * (B_jp - two * centerB + B_jm);
        Expr term_k = alpha * (B_kp - two * centerB + B_km);

        A_from_B(k, j, i) = term_i + term_j + term_k + centerB;
    }

    // We want to update only the interior region:
    //   i, j, k in [1, n-2]
    // The boundary values remain unchanged (exactly as in the C code).
    //
    // We'll realize into cropped "interior" views that alias the
    // underlying A and B storage, so that:
    //   - interior points are overwritten by the stencil
    //   - boundary points (index 0 and n-1) are untouched
    Halide::Buffer<num_t, 3> B_interior =
        B.cropped(0, 1, n - 2)
         .cropped(1, 1, n - 2)
         .cropped(2, 1, n - 2);

    Halide::Buffer<num_t, 3> A_interior =
        A.cropped(0, 1, n - 2)
         .cropped(1, 1, n - 2)
         .cropped(2, 1, n - 2);

    // --------------------------------------------------------------------
    // Scheduling: improve data locality, vectorization, and parallelism.
    // --------------------------------------------------------------------
    {
        // Choose a reasonable vector width for the current CPU and element type.
        Target target = get_host_target();
        const int vec_width = target.natural_vector_size<num_t>();

        // Both stencils share the same optimal schedule:
        //
        // - Make k (dimension 0) the innermost loop: it is contiguous in
        //   memory (C's k index) so this maximizes spatial locality.
        // - Parallelize across i (outermost index): each i-slab is
        //   independent, giving coarse-grain parallelism.
        // - Vectorize across k: use SIMD along the contiguous dimension.
        //
        // Note: The bounds [1, n-2] are imposed implicitly by realizing
        // into the cropped interior buffers; we rely on that here.
        B_from_A
            .compute_root()
            .reorder(k, j, i)  // innermost -> outermost: k, j, i
            .parallel(i);      // parallel over i-slabs

